package com.nutritionplatform.nutritionprofile.service;
import com.nutritionplatform.nutritionprofile.domain.NutritionProfile; import com.nutritionplatform.nutritionprofile.dto.NutritionProfileRequest; import com.nutritionplatform.nutritionprofile.repository.NutritionProfileRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class NutritionProfileService { private final NutritionProfileRepository profiles; public NutritionProfileService(NutritionProfileRepository profiles){this.profiles=profiles;} public NutritionProfile get(UUID id){return profiles.findByUserId(id).orElse(null);} @Transactional public NutritionProfile save(UUID id,NutritionProfileRequest r){var p=profiles.findByUserId(id).orElseGet(()->new NutritionProfile(id));p.update(r.displayName(),r.birthDate(),r.heightCm(),r.currentWeightKg(),r.goal(),r.activityLevel(),r.dietaryPreferences(),r.allergies(),r.restrictions());return profiles.save(p);} }
